44	    private function categoryMap(): array
45	    {
46	        global $work_category_types, $work_category_slugs;
47	        if (!is_array($work_category_types) || $work_category_types === []) {
48	            return [];
49	        }
50	        $slugs = is_array($work_category_slugs ?? null) ? $work_category_slugs : [];
51	        $map = [];
52	        foreach ($work_category_types as $id => $label) {
53	            $id = (int) $id;
54	            $slug = isset($slugs[$id]) ? trim((string) $slugs[$id]) : '';
55	            if ($slug === '') {
56	                $slug = 'category-' . $id;
57	            }
58	            $map[$id] = [
59	                'slug' => strtolower($slug),
60	                'label' => (string) $label,
61	            ];
62	        }
63	
64	        return $map;
65	    }
