106	    public function resolveCategory(?string $category): ?string
107	    {
108	        $value = strtolower(trim((string) $category));
109	        if ($value === '' || $value === self::ALL_CATEGORY_SLUG) {
110	            return null;
111	        }
112	
113	        foreach ($this->categoryMap() as $row) {
114	            if ($row['slug'] !== $value) {
115	                continue;
116	            }
117	
118	            return $value;
119	        }
120	
121	        return null;
122	    }
