124	    /**
125	     * @return array{
126	     *   items: array<int, array{
127	     *     no: string,
128	     *     title: string,
129	     *     thumbnailImage: string,
130	     *     thumbnailVideo: ?string,
131	     *     category: string,
132	     *     categoryLabel: string,
133	     *     tagLabels: array<int, string>,
134	     *     detailPath: string,
135	     *     modalPath: string,
136	     *     client: ?string,
137	     *     updatedAtLabel: ?string
138	     *   }>,
139	     *   nextOffset: ?int,
140	     *   hasMore: bool
141	     * }
142	     */
143	    public function getList(int $offset, int $limit, ?string $category = null, bool $featured = false): array
144	    {
145	        $normalizedOffset = max(0, $offset);
146	        $normalizedLimit = max(1, min(self::MAX_LIMIT, $limit));
147	        $rows = $this->selectRows($normalizedOffset, $normalizedLimit + 1, $category, $featured);
148	        $hasMore = count($rows) > $normalizedLimit;
149	        if ($hasMore) {
150	            array_pop($rows);
151	        }
152	
153	        $items = array_map(
154	            fn(array $row): array => $this->mapListItem($row),
155	            $rows
156	        );
157	
158	        return [
159	            'items' => array_values($items),
160	            'nextOffset' => $hasMore ? $normalizedOffset + count($items) : null,
161	            'hasMore' => $hasMore,
162	        ];
163	    }
