189	    public function getDetail(string $no): ?array
190	    {
191	        $id = trim($no);
192	        if ($id === '') {
193	            return null;
194	        }
195	
196	        $sql = <<<SQL
197	SELECT
198	    `id`,
199	    `title`,
200	    `sub_title`,
201	    `is_awarded`,
202	    `award_type`,
203	    `award_detail`,
204	    `thumb_image`,
205	    `services`,
206	    `client`,
207	    `category`,
208	    `link_url`,
209	    `video`,
210	    `overview`,
211	    `contents`,
212	    `file_attach1`,
213	    `file_attach2`,
214	    `file_attach3`,
215	    `file_attach4`,
216	    `file_attach5`,
217	    `tag`,
218	    `created_at`,
219	    `updated_at`
220	FROM `nb_works`
221	WHERE `id` = :id
222	  AND `is_visible` = :is_visible
223	  AND `deleted_at` IS NULL
224	LIMIT 1
225	SQL;
226	
227	        $statement = $this->pdo->prepare($sql);
228	        $statement->bindValue(':id', $id, \PDO::PARAM_STR);
229	        $statement->bindValue(':is_visible', self::VISIBLE_VALUE, \PDO::PARAM_INT);
230	        $statement->execute();
231	        $row = $statement->fetch();
232	
233	        if (!is_array($row)) {
234	            return null;
235	        }
236	
237	        return $this->mapDetailItem($row);
238	    }
