240	    /**
241	     * @return array<int, array<string, mixed>>
242	     */
243	    private function selectRows(int $offset, int $limit, ?string $category, bool $featured = false): array
244	    {
245	        $conditions = [
246	            '`is_visible` = :is_visible',
247	            '`deleted_at` IS NULL',
248	        ];
249	        $bindings = [
250	            ':is_visible' => [self::VISIBLE_VALUE, \PDO::PARAM_INT],
251	        ];
252	
253	        if ($featured) {
254	            $conditions[] = "(`is_awarded` = 'Y' OR JSON_CONTAINS(`category`, CAST(1 AS JSON)))";
255	        }
256	
257	        $resolvedCategory = $this->resolveCategory($category);
258	        if ($resolvedCategory !== null) {
259	            $categoryId = $this->resolveCategoryId($resolvedCategory);
260	            if ($categoryId === null) {
261	                return [];
262	            }
263	
264	            $conditions[] = 'JSON_CONTAINS(`category`, CAST(:category_json AS JSON))';
265	            $bindings[':category_json'] = [(string) $categoryId, \PDO::PARAM_STR];
266	        }
267	
268	        $whereClause = 'WHERE ' . implode(' AND ', $conditions);
269	        $sql = <<<SQL
270	SELECT
271	    `id`,
272	    `title`,
273	    `thumb_image`,
274	    `video`,
275	    `client`,
276	    `category`,
277	    `tag`,
278	    `is_awarded`,
279	    `updated_at`,
280	    `created_at`,
281	    `file_attach1`,
282	    `file_attach2`,
283	    `file_attach3`,
284	    `file_attach4`,
285	    `file_attach5`
286	FROM `nb_works`
287	{$whereClause}
288	ORDER BY (`is_awarded` = 'Y') DESC, `sort_no` DESC, `id` DESC
289	LIMIT :limit OFFSET :offset
290	SQL;
291	
292	        $statement = $this->pdo->prepare($sql);
293	        foreach ($bindings as $name => [$value, $type]) {
294	            $statement->bindValue($name, $value, $type);
295	        }
296	        $statement->bindValue(':limit', $limit, \PDO::PARAM_INT);
297	        $statement->bindValue(':offset', $offset, \PDO::PARAM_INT);
298	        $statement->execute();
299	
300	        $rows = $statement->fetchAll();
301	        return is_array($rows) ? $rows : [];
302	    }
