304	    /**
305	     * 프런트 목록과 동일: 노출 중이고 삭제되지 않은 nb_works 행 수.
306	     */
307	    public function getPublicWorksCount(): int
308	    {
309	        $sql = <<<'SQL'
310	SELECT COUNT(*) AS `cnt`
311	FROM `nb_works`
312	WHERE `deleted_at` IS NULL
313	  AND `is_visible` = :is_visible
314	SQL;
315	        $statement = $this->pdo->prepare($sql);
316	        $statement->bindValue(':is_visible', self::VISIBLE_VALUE, \PDO::PARAM_INT);
317	        $statement->execute();
318	        $row = $statement->fetch();
319	        if (!is_array($row) || !array_key_exists('cnt', $row)) {
320	            return 0;
321	        }
322	
323	        return max(0, (int) $row['cnt']);
324	    }
