435	    private function resolveDetailImages(array $row, string $thumbnailImage): array
436	    {
437	        $images = [];
438	        foreach (self::DETAIL_IMAGE_FIELDS as $field) {
439	            $url = $this->buildAssetUrl($row[$field] ?? null);
440	            if ($url === null) {
441	                continue;
442	            }
443	
444	            $images[] = $url;
445	        }
446	
447	        if ($images !== []) {
448	            return array_values(array_unique($images));
449	        }
450	
451	        return [$thumbnailImage];
