454	    /**
455	     * @return array<int, array{slug: string, label: string}>
456	     */
457	    private function resolveCategoryItems($rawValue): array
458	    {
459	        $categoryIds = $this->normalizeIntegerList($rawValue);
460	        $items = [];
461	        $catMap = $this->categoryMap();
462	        foreach ($categoryIds as $categoryId) {
463	            if (!array_key_exists($categoryId, $catMap)) {
464	                continue;
465	            }
466	
467	            $items[] = $catMap[$categoryId];
468	        }
469	
470	        if ($items !== []) {
471	            return $items;
472	        }
473	
474	        return [
475	            [
476	                'slug' => 'other',
477	                'label' => '기타',
478	            ],
479	        ];
480	    }
