483	     * @return array<int, string>
484	     */
485	    private function resolveServiceLabels($rawValue): array
486	    {
487	        $map = $this->serviceLabelMap();
488	        $serviceIds = $this->normalizeIntegerList($rawValue);
489	        $labels = [];
490	        foreach ($serviceIds as $serviceId) {
