501	    /**
502	     * @return array{label: string, icon: ?string, detail: ?string}|null
503	     */
504	    private function resolveAward($awardedValue, $awardTypeValue, $awardDetailValue = null): ?array
505	    {
506	        global $work_award_types;
507	        $awardedFlag = strtoupper(trim((string) $awardedValue));
508	        if (!in_array($awardedFlag, ['Y', '1'], true)) {
509	            return null;
510	        }
511	
512	        $awardType = (int) $awardTypeValue;
513	        $labels = is_array($work_award_types ?? null) ? $work_award_types : [];
514	        if (!array_key_exists($awardType, $labels)) {
515	            return null;
516	        }
517	
518	        $detail = $this->normalizeText($awardDetailValue);
519	
520	        return [
521	            'label' => (string) $labels[$awardType],
522	            'icon' => self::AWARD_ICON_MAP[$awardType] ?? null,
523	            'detail' => $detail,
524	        ];
525	    }
