527	    private function resolveCategoryId(string $slug): ?int
528	    {
529	        $needle = strtolower(trim($slug));
530	        foreach ($this->categoryMap() as $categoryId => $categoryData) {
531	            if ($categoryData['slug'] !== $needle) {
532	                continue;
533	            }
534	
535	            return $categoryId;
536	        }
537	
538	        return null;
539	    }
