541	    /**
542	     * @param array<string, mixed> $row
543	     */
544	    private function resolveThumbnailImage(array $row): string
545	    {
546	        $thumbnail = $this->buildAssetUrl($row['thumb_image'] ?? null);
547	        if ($thumbnail !== null) {
548	            return $thumbnail;
549	        }
550	
551	        foreach (self::DETAIL_IMAGE_FIELDS as $field) {
552	            $fallback = $this->buildAssetUrl($row[$field] ?? null);
553	            if ($fallback === null) {
554	                continue;
555	            }
556	
557	            return $fallback;
558	        }
559	
560	        return base_path(self::PLACEHOLDER_IMAGE_PATH);
561	    }
