563	    private function resolveVideoUrl($rawValue): ?string
564	    {
565	        $decoded = $this->decodeJsonValue($rawValue);
566	
567	        if (is_string($decoded)) {
568	            $url = $this->normalizeAssetOrUrl($decoded);
569	            if ($url !== null) {
570	                return $url;
571	            }
572	        } elseif (is_array($decoded)) {
573	            foreach ($decoded as $value) {
574	                if (!is_string($value)) {
575	                    continue;
576	                }
577	                $url = $this->normalizeAssetOrUrl($value);
578	                if ($url !== null) {
579	                    return $url;
580	                }
581	            }
582	        }
583	
584	        return null;
585	    }
