631	    /**
632	     * @return array<int, int>
633	     */
634	    private function normalizeIntegerList($value): array
635	    {
636	        $decoded = $this->decodeJsonValue($value);
637	        if (is_int($decoded)) {
638	            return [$decoded];
639	        }
640	
641	        if (is_string($decoded) && preg_match('/^\d+$/', $decoded) === 1) {
642	            return [(int) $decoded];
643	        }
644	
645	        if (!is_array($decoded)) {
646	            return [];
647	        }
648	
649	        $items = [];
650	        foreach ($decoded as $item) {
651	            if (is_int($item)) {
652	                $items[] = $item;
653	                continue;
654	            }
655	
656	            if (!is_string($item) || preg_match('/^\d+$/', $item) !== 1) {
657	                continue;
658	            }
659	
660	            $items[] = (int) $item;
661	        }
662	
663	        return array_values(array_unique($items));
664	    }
665	
666	    /**
667	     * @return array<int, string>
668	     */
669	    private function normalizeStringList($value): array
670	    {
671	        $decoded = $this->decodeJsonValue($value);
672	        if (is_string($decoded)) {
673	            $normalized = trim($decoded, " \t\n\r\0\x0B\"'");
674	            return $normalized === '' ? [] : [$normalized];
675	        }
676	
677	        if (!is_array($decoded)) {
678	            return [];
679	        }
680	
681	        $items = [];
682	        foreach ($decoded as $item) {
683	            if (!is_string($item)) {
684	                continue;
685	            }
686	
687	            $normalized = trim($item);
688	            if ($normalized === '') {
689	                continue;
690	            }
691	
692	            $items[] = $normalized;
