116	
117	  async load(state: WorksPageState): Promise<WorkProjectItem[]> {
118	    this._fetchAbortController?.abort();
119	    this._fetchAbortController = new AbortController();
120	    const signal = this._fetchAbortController.signal;
121	    const projects: WorkProjectItem[] = [];
122	    let offset = 0;
123	    let hasMore = true;
124	
125	    while (hasMore && projects.length < WORK_CANVAS_CONFIG.totalCards) {
126	      const remaining = WORK_CANVAS_CONFIG.totalCards - projects.length;
127	      const response = await fetchWorksList(
128	        offset,
129	        Math.min(WORKS_LIST_API_MAX_LIMIT, remaining),
130	        state.category,
131	        signal,
132	      );
133	      response.items.forEach((item, index) => {
134	        projects.push(createWorkProjectItem(item, projects.length + index));
135	      });
136	      hasMore = response.hasMore;
137	      offset = response.nextOffset ?? offset + response.items.length;
138	      if (response.items.length === 0) {
139	        hasMore = false;
140	      }
141	    }
142	
143	    this._fetchAbortController = null;
144	    return projects;
145	  }
146	
147	  isAbortedError(error: unknown): boolean {
148	    return error instanceof DOMException && error.name === "AbortError";
149	  }
