### 5. THREE.JS TEXTURE LOADING PATTERN (Current Implementation)

**File:** `/c/Users/edn_y/renew_nineonelabs/resource/ts/ui/WorkCard.ts`

**Image Loading via Promise:**
```typescript
static loadImage(url: string): Promise<HTMLImageElement> {
  const trimmed = url.trim();
  return new Promise((resolve, reject) => {
    if (!trimmed) {
      reject(new Error("WorkCard: empty image url"));
      return;
    }
    const image = new Image();
    // Enable CORS if not data/blob URL
    if (!trimmed.startsWith("data:") && !trimmed.startsWith("blob:")) {
      image.crossOrigin = "anonymous";
    }
    image.onload = () => resolve(image);
    image.onerror = () => reject(new Error(`WorkCard: failed to load image ${trimmed}`));
    image.src = trimmed;  // <-- Trigger load
  });
}
```

**Canvas Texture Creation (from HTMLImageElement):**
```typescript
static buildTexture(
  proj: WorkProjectItem,
  size: WorkCardSize,
  image?: HTMLImageElement | null,
): THREE.CanvasTexture {
  const canvas = document.createElement("canvas");
  canvas.width = CANVAS_W * CANVAS_DPI_SCALE;
  canvas.height = height * CANVAS_DPI_SCALE;

  const ctx = canvas.getContext("2d");
  drawCardToContext(ctx, proj, size, image);  // <-- Draws image onto canvas

  const texture = new THREE.CanvasTexture(canvas);
  texture.flipY = false;
  texture.premultiplyAlpha = false;
  texture.anisotropy = 16;
  return texture;
}
```

**Update Texture with Loaded Image:**
```typescript
static updateTextureImage(
  texture: THREE.CanvasTexture,
  proj: WorkProjectItem,
  size: WorkCardSize,
  image: HTMLImageElement,
  renderOptions: WorkCardRenderOptions,
): void {
  const canvas = texture.image as HTMLCanvasElement;
  const ctx = canvas.getContext("2d");
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawCardToContext(ctx, proj, size, image);
  texture.needsUpdate = true;  // <-- Notify Three.js to re-upload
}
```

